<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Algorithm Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --background: #090d18;
      --panel: #111827;
      --panel-border: #263249;
      --text: #e5e7eb;
      --muted: #94a3b8;
      --accent: #60a5fa;
      --accent-light: #93c5fd;
      --active: #fbbf24;
      --success: #34d399;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      padding: 24px;
      display: grid;
      place-items: center;
      overflow-x: hidden;
      background:
        radial-gradient(circle at top, #17213a 0, transparent 38%),
        var(--background);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    main {
      width: min(1050px, 100%);
    }

    header {
      margin-bottom: 20px;
      text-align: center;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.7rem, 4vw, 2.5rem);
      letter-spacing: -0.04em;
    }

    header p {
      margin: 0;
      color: var(--muted);
    }

    .panel {
      padding: clamp(16px, 3vw, 28px);
      border: 1px solid var(--panel-border);
      border-radius: 18px;
      background: color-mix(in srgb, var(--panel) 92%, transparent);
      box-shadow: 0 24px 65px rgb(0 0 0 / 35%);
    }

    #bars {
      height: min(58vh, 520px);
      min-height: 280px;
      padding: 16px 12px 0;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      gap: clamp(2px, 0.55vw, 7px);
      overflow: hidden;
      border: 1px solid #29354c;
      border-radius: 12px;
      background:
        linear-gradient(to top, rgb(96 165 250 / 8%), transparent 60%),
        repeating-linear-gradient(
          to top,
          transparent 0,
          transparent calc(20% - 1px),
          rgb(148 163 184 / 8%) 20%
        ),
        #0b1220;
    }

    .bar {
      width: 100%;
      max-width: 30px;
      min-width: 2px;
      min-height: 2px;
      border-radius: 5px 5px 1px 1px;
      background: linear-gradient(to top, #2563eb, var(--accent-light));
      box-shadow: 0 0 12px rgb(96 165 250 / 18%);
      transition: height 80ms ease, background 80ms ease, transform 80ms ease;
    }

    .bar.active {
      z-index: 1;
      background: linear-gradient(to top, #d97706, var(--active));
      box-shadow: 0 0 18px rgb(251 191 36 / 45%);
      transform: translateY(-3px);
    }

    .bar.complete {
      background: linear-gradient(to top, #059669, var(--success));
      box-shadow: 0 0 14px rgb(52 211 153 / 25%);
    }

    .controls {
      margin-top: 22px;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
    }

    button {
      min-width: 112px;
      padding: 11px 18px;
      border: 1px solid #334155;
      border-radius: 9px;
      background: #1e293b;
      color: var(--text);
      font: inherit;
      font-weight: 650;
      cursor: pointer;
      transition: background 150ms ease, border-color 150ms ease,
        transform 150ms ease, opacity 150ms ease;
    }

    button:hover:not(:disabled) {
      border-color: #64748b;
      background: #2b3a50;
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgb(96 165 250 / 45%);
      outline-offset: 2px;
    }

    button:disabled {
      cursor: wait;
      opacity: 0.55;
    }

    #sort {
      border-color: #3b82f6;
      background: #2563eb;
      color: white;
    }

    #sort:hover:not(:disabled) {
      border-color: #60a5fa;
      background: #3b82f6;
    }

    #status {
      min-height: 1.5em;
      margin: 15px 0 0;
      color: var(--muted);
      text-align: center;
      font-size: 0.92rem;
    }

    @media (max-width: 520px) {
      body {
        padding: 12px;
      }

      .panel {
        padding: 12px;
      }

      #bars {
        min-height: 240px;
        padding-inline: 6px;
      }

      button {
        min-width: 92px;
        flex: 1;
      }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>Sorting Visualizer</h1>
      <p>Bubble sort, animated one comparison at a time</p>
    </header>

    <section class="panel" aria-label="Sorting algorithm visualizer">
      <div id="bars" aria-label="Array values displayed as vertical bars"></div>

      <div class="controls">
        <button id="sort" type="button">Sort</button>
        <button id="shuffle" type="button">Shuffle</button>
        <button id="reset" type="button">Reset</button>
      </div>

      <p id="status" aria-live="polite">Ready</p>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const barsElement = document.getElementById("bars");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");
      const statusElement = document.getElementById("status");

      const initialArray = [
        34, 76, 18, 92, 45, 61, 27, 83, 12, 70,
        39, 95, 53, 21, 66, 8, 88, 48, 31, 79,
        15, 57, 98, 25, 73, 42, 63, 5, 86, 36,
        68, 10, 90, 51, 29, 81
      ];

      let values = initialArray.slice();
      let index = 0;
      let passEnd = Math.max(0, values.length - 1);
      let swappedInPass = false;
      let finished = values.length < 2;
      let animationToken = 0;
      let running = false;

      function isAscending() {
        for (let i = 1; i < values.length; i++) {
          if (values[i - 1] > values[i]) {
            return false;
          }
        }
        return true;
      }

      function resetSortState() {
        index = 0;
        passEnd = Math.max(0, values.length - 1);
        swappedInPass = false;
        finished = values.length < 2;
      }

      function render(activeIndices = [], complete = finished || isAscending()) {
        barsElement.replaceChildren();

        let minimum = 0;
        let maximum = 1;

        if (values.length) {
          minimum = values[0];
          maximum = values[0];

          for (let i = 1; i < values.length; i++) {
            if (values[i] < minimum) minimum = values[i];
            if (values[i] > maximum) maximum = values[i];
          }
        }

        const positiveOnly = minimum >= 0;
        const scaleMaximum = positiveOnly ? Math.max(1, maximum) : maximum - minimum || 1;

        for (let i = 0; i < values.length; i++) {
          const bar = document.createElement("div");
          const normalized = positiveOnly
            ? values[i] / scaleMaximum
            : (values[i] - minimum) / scaleMaximum;

          bar.className = "bar";
          bar.style.height = `${Math.max(0.01, normalized) * 100}%`;
          bar.dataset.value = String(values[i]);
          bar.title = String(values[i]);
          bar.setAttribute("aria-label", `Value ${values[i]}`);

          if (activeIndices.includes(i)) {
            bar.classList.add("active");
          } else if (complete) {
            bar.classList.add("complete");
          }

          barsElement.appendChild(bar);
        }
      }

      function setArray(nextArray) {
        if (!Array.isArray(nextArray)) {
          throw new TypeError("setArray expects an array of finite numbers.");
        }

        const copy = nextArray.map((value) => Number(value));

        for (let i = 0; i < copy.length; i++) {
          if (!Number.isFinite(copy[i])) {
            throw new TypeError("setArray expects an array of finite numbers.");
          }
        }

        cancelAnimation();
        values = copy;
        resetSortState();
        render();
        statusElement.textContent = isAscending() ? "Already sorted" : "Ready";
      }

      function sortStep() {
        if (finished) {
          render([], true);
          return true;
        }

        if (values.length < 2 || passEnd <= 0) {
          finished = true;
          render([], true);
          return true;
        }

        const left = index;
        const right = index + 1;

        if (values[left] > values[right]) {
          const temporary = values[left];
          values[left] = values[right];
          values[right] = temporary;
          swappedInPass = true;
        }

        index++;

        if (index >= passEnd) {
          if (!swappedInPass) {
            finished = true;
          } else {
            passEnd--;
            index = 0;
            swappedInPass = false;

            if (passEnd <= 0) {
              finished = true;
            }
          }
        }

        render(finished ? [] : [left, right], finished);
        return finished;
      }

      function cancelAnimation() {
        animationToken++;
        running = false;
        sortButton.disabled = false;
      }

      async function animateSort() {
        if (running) return;

        running = true;
        sortButton.disabled = true;
        statusElement.textContent = "Sorting…";
        const token = ++animationToken;

        while (token === animationToken) {
          const done = sortStep();

          if (done) {
            running = false;
            sortButton.disabled = false;
            statusElement.textContent = "Sorted ascending";
            return;
          }

          await new Promise((resolve) => setTimeout(resolve, 42));
        }
      }

      function shuffleValues() {
        cancelAnimation();

        for (let i = values.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          const temporary = values[i];
          values[i] = values[j];
          values[j] = temporary;
        }

        resetSortState();
        render();
        statusElement.textContent = "Shuffled";
      }

      sortButton.addEventListener("click", animateSort);
      shuffleButton.addEventListener("click", shuffleValues);
      resetButton.addEventListener("click", () => {
        setArray(initialArray);
        statusElement.textContent = "Reset";
      });

      window.viz = {
        array() {
          return values.slice();
        },
        setArray,
        sortStep,
        sorted: isAscending
      };

      render();
    })();
  </script>
</body>
</html>
